<!doctype html><html lang="{{ session('portal_lang','en') }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ t('Global Audit Logs','গ্লোবাল অডিট লগ') }}</title><style>body{background:#101a2c;color:#edf3fc;font:14px system-ui;padding:24px;max-width:1200px;margin:auto}a{color:#afa5ff}.card{background:#1c283c;padding:18px;border-radius:14px;margin:18px 0}input,button{padding:10px;background:#101a2c;color:#fff;border:1px solid #4b5670;border-radius:8px}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #3c4658;vertical-align:top}details{max-width:450px;overflow-wrap:anywhere}pre{white-space:pre-wrap;font-size:11px}</style></head><body><p><a href="{{ route('authority.dashboard') }}">{{ t('Dashboard','ড্যাশবোর্ড') }}</a></p><h1>{{ t('Global Audit Logs','গ্লোবাল অডিট লগ') }}</h1><p>{{ t('Platform-wide and business-level events. Credential fields are omitted.','প্ল্যাটফর্ম ও ব্যবসার কার্যক্রম। গোপন তথ্য রাখা হয়নি।') }}</p><div class="card"><form method="GET"><input type="number" min="1" name="business_id" value="{{ request('business_id') }}" placeholder="Business ID"><input name="table" value="{{ request('table') }}" placeholder="Table"><button>{{ t('Filter','ফিল্টার') }}</button></form></div><div class="card" style="overflow-x:auto"><table><thead><tr><th>Time</th><th>Business</th><th>Record</th><th>Action</th><th>Actor</th><th>Diff</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at }}</td><td>{{ $log->business_id ?? 'Global' }}</td><td>{{ $log->subject_table }} #{{ $log->subject_id }}</td><td>{{ $log->action }}</td><td>{{ $log->actor_name ?: ($log->actor_id ?: 'System') }}</td><td><details><summary>{{ t('View','দেখুন') }}</summary><pre>{{ json_encode(['before'=>$log->old_values,'after'=>$log->new_values],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE) }}</pre></details></td></tr>@empty<tr><td colspan="6">No logs found.</td></tr>@endforelse</tbody></table></div>{{ $logs->links() }}</body></html>